package dev.mariscore.listener;import dev.mariscore.*;import dev.mariscore.config.Settings;import dev.mariscore.storage.Storage;import org.bukkit.event.*;import org.bukkit.event.player.PlayerJoinEvent;
public final class JoinListener implements Listener{private final MarisCorePlugin p;private final Storage s;private final Settings cfg;public JoinListener(MarisCorePlugin p,Storage s,Settings cfg){this.p=p;this.s=s;this.cfg=cfg;}@EventHandler public void onJoin(PlayerJoinEvent e){s.ensure(e.getPlayer().getUniqueId(),e.getPlayer().getName(),cfg.startingMoney,cfg.startingShards);}}
